package com.dy.artisan3d.data.mapperimport com.dy.artisan3d.data.model.BrandDetailsDtoimport com.dy.artisan3d.data.model.CategoryDetailsDtoimport com.dy.artisan3d.data.model.ColorDtoimport com.dy.artisan3d.data.model.MaterialDtoimport com.dy.artisan3d.data.model.ProductDetailsDtoimport com.dy.artisan3d.data.model.ProductImagesimport com.dy.artisan3d.data.model.ProductInfoDtoimport com.dy.artisan3d.data.model.StatusDtoimport com.dy.artisan3d.data.model.TagDtoimport com.dy.artisan3d.domain.model.BrandDetailsimport com.dy.artisan3d.domain.model.CategoryDetailsimport com.dy.artisan3d.domain.model.Colorimport com.dy.artisan3d.domain.model.Materialimport com.dy.artisan3d.domain.model.ProductDetailimport com.dy.artisan3d.domain.model.ProductDetailsimport com.dy.artisan3d.domain.model.Statusimport com.dy.artisan3d.domain.model.Tagimport com.dy.artisan3d.util.Constants.FILE_URLfun ProductDetailsDto.toDomain(language: String = "en"): ProductDetails {    val translation = translations[language] ?: translations["en"]    ?: throw IllegalStateException("No translation found")    return ProductDetails(        id = id,        slug = slug,        name = translation.name,        description = translation.description,        category = category.toDomain(language),        brand = brand!!.toDomain(language),        status = status.toDomain(language),        details = details.firstOrNull()?.toDomain(language)            ?: throw IllegalStateException("No details found"),        images = images.toDomain(),        createdAt = createdAt,        updatedAt = updatedAt    )}// Funksiya sarlavhasini ? bilan o'zgartiringfun CategoryDetailsDto?.toDomain(language: String): CategoryDetails {    // Agar dto null bo'lsa, xato tashlaymiz yoki default qaytaramiz    val dto = this ?: throw IllegalStateException("Category is null")    val translation = dto.translations[language] ?: dto.translations["en"]    ?: throw IllegalStateException("No category translation found")    return CategoryDetails(        id = dto.id,        slug = dto.slug,        name = translation.name    )}fun BrandDetailsDto.toDomain(language: String): BrandDetails {    val translation = translations[language] ?: translations["en"]    ?: throw IllegalStateException("No brand translation found")    return BrandDetails(        id = id,        name = translation.name,        address = translation.address,        image = image    )}fun StatusDto.toDomain(language: String): Status {    val translation = translations[language] ?: translations["en"]    ?: throw IllegalStateException("No status translation found")    return Status(        id = id,        name = translation.name    )}fun ProductInfoDto.toDomain(language: String): ProductDetail {    return ProductDetail(        id = id,        colors = colors.map { it.toDomain(language) },        materials = materials.map { it.toDomain(language) },        tags = tags.map { it.toDomain(language) },        madeDate = madeDate,        size = size    )}fun ColorDto.toDomain(language: String): Color {    val translation = translations[language] ?: translations["en"]    ?: throw IllegalStateException("No color translation found")    return Color(        id = id,        name = translation.name,        code = code    )}fun MaterialDto.toDomain(language: String): Material {    val translation = translations[language] ?: translations["en"]    ?: throw IllegalStateException("No material translation found")    return Material(        id = id,        name = translation.name,        slug = slug    )}fun TagDto.toDomain(language: String): Tag {    val translation = translations[language] ?: translations["en"]    ?: throw IllegalStateException("No tag translation found")    return Tag(        id = id,        name = translation.name,        slug = slug    )}fun ProductImages.toDomain(): com.dy.artisan3d.domain.model.ProductImages {    return com.dy.artisan3d.domain.model.ProductImages(        main = FILE_URL+main,        glb = FILE_URL+glb,        extra = extra.map { FILE_URL+it }    )}